/*
 * AES block cipher core (FIPS-197).
 *
 * The state is held as a flat 16-byte array using the standard column-major
 * mapping: state[row][col] lives at index `row + 4 * col`, which means the
 * flat array is exactly the input byte order and no transposition is needed
 * on the way in or out.
 */

import {
  S_BOX,
  INV_S_BOX,
  MUL_2,
  MUL_3,
  MUL_9,
  MUL_11,
  MUL_13,
  MUL_14,
  RCON,
} from './tables.mjs';

export const BLOCK_SIZE = 16;

/** Key lengths in bytes that map to AES-128 / AES-192 / AES-256. */
const VALID_KEY_SIZES = new Set([16, 24, 32]);

export function isValidKeySize(length) {
  return VALID_KEY_SIZES.has(length);
}

/**
 * Expand a cipher key into (Nr + 1) round keys, returned as one flat byte
 * array so AddRoundKey can XOR a contiguous 16-byte slice per round.
 */
function expandKey(key) {
  const nk = key.length / 4;
  const rounds = nk + 6;
  const wordCount = 4 * (rounds + 1);
  const schedule = new Uint8Array(4 * wordCount);
  schedule.set(key, 0);

  for (let i = nk; i < wordCount; i += 1) {
    const prev = 4 * (i - 1);
    let t0 = schedule[prev];
    let t1 = schedule[prev + 1];
    let t2 = schedule[prev + 2];
    let t3 = schedule[prev + 3];

    if (i % nk === 0) {
      // RotWord, SubWord, then fold in the round constant.
      const rotated = [t1, t2, t3, t0];
      t0 = S_BOX[rotated[0]] ^ RCON[i / nk];
      t1 = S_BOX[rotated[1]];
      t2 = S_BOX[rotated[2]];
      t3 = S_BOX[rotated[3]];
    } else if (nk > 6 && i % nk === 4) {
      // AES-256 applies an extra SubWord midway through each key block.
      t0 = S_BOX[t0];
      t1 = S_BOX[t1];
      t2 = S_BOX[t2];
      t3 = S_BOX[t3];
    }

    const back = 4 * (i - nk);
    const out = 4 * i;
    schedule[out] = schedule[back] ^ t0;
    schedule[out + 1] = schedule[back + 1] ^ t1;
    schedule[out + 2] = schedule[back + 2] ^ t2;
    schedule[out + 3] = schedule[back + 3] ^ t3;
  }

  return { schedule, rounds };
}

function addRoundKey(state, schedule, round) {
  const offset = BLOCK_SIZE * round;
  for (let i = 0; i < BLOCK_SIZE; i += 1) state[i] ^= schedule[offset + i];
}

function subBytes(state, box) {
  for (let i = 0; i < BLOCK_SIZE; i += 1) state[i] = box[state[i]];
}

/** Row r rotates left by r positions. */
function shiftRows(state) {
  for (let r = 1; r < 4; r += 1) {
    const row = [state[r], state[r + 4], state[r + 8], state[r + 12]];
    for (let c = 0; c < 4; c += 1) state[r + 4 * c] = row[(c + r) % 4];
  }
}

/** Row r rotates right by r positions. */
function invShiftRows(state) {
  for (let r = 1; r < 4; r += 1) {
    const row = [state[r], state[r + 4], state[r + 8], state[r + 12]];
    for (let c = 0; c < 4; c += 1) state[r + 4 * c] = row[(c - r + 4) % 4];
  }
}

function mixColumns(state) {
  for (let c = 0; c < 4; c += 1) {
    const i = 4 * c;
    const a0 = state[i];
    const a1 = state[i + 1];
    const a2 = state[i + 2];
    const a3 = state[i + 3];
    state[i] = MUL_2[a0] ^ MUL_3[a1] ^ a2 ^ a3;
    state[i + 1] = a0 ^ MUL_2[a1] ^ MUL_3[a2] ^ a3;
    state[i + 2] = a0 ^ a1 ^ MUL_2[a2] ^ MUL_3[a3];
    state[i + 3] = MUL_3[a0] ^ a1 ^ a2 ^ MUL_2[a3];
  }
}

function invMixColumns(state) {
  for (let c = 0; c < 4; c += 1) {
    const i = 4 * c;
    const a0 = state[i];
    const a1 = state[i + 1];
    const a2 = state[i + 2];
    const a3 = state[i + 3];
    state[i] = MUL_14[a0] ^ MUL_11[a1] ^ MUL_13[a2] ^ MUL_9[a3];
    state[i + 1] = MUL_9[a0] ^ MUL_14[a1] ^ MUL_11[a2] ^ MUL_13[a3];
    state[i + 2] = MUL_13[a0] ^ MUL_9[a1] ^ MUL_14[a2] ^ MUL_11[a3];
    state[i + 3] = MUL_11[a0] ^ MUL_13[a1] ^ MUL_9[a2] ^ MUL_14[a3];
  }
}

/**
 * Single-block AES. Mirrors pyaes.AES: the constructor validates the key size
 * and builds the schedule; encrypt/decrypt transform exactly one 16-byte
 * block and return a plain Array of byte values.
 */
export class AES {
  constructor(key) {
    const { schedule, rounds } = expandKey(key);
    this.schedule = schedule;
    this.rounds = rounds;
  }

  encryptBlock(block) {
    const state = Uint8Array.from(block);
    addRoundKey(state, this.schedule, 0);

    for (let round = 1; round < this.rounds; round += 1) {
      subBytes(state, S_BOX);
      shiftRows(state);
      mixColumns(state);
      addRoundKey(state, this.schedule, round);
    }

    // The last round omits MixColumns.
    subBytes(state, S_BOX);
    shiftRows(state);
    addRoundKey(state, this.schedule, this.rounds);

    return Array.from(state);
  }

  decryptBlock(block) {
    const state = Uint8Array.from(block);
    addRoundKey(state, this.schedule, this.rounds);

    for (let round = this.rounds - 1; round > 0; round -= 1) {
      invShiftRows(state);
      subBytes(state, INV_S_BOX);
      addRoundKey(state, this.schedule, round);
      invMixColumns(state);
    }

    invShiftRows(state);
    subBytes(state, INV_S_BOX);
    addRoundKey(state, this.schedule, 0);

    return Array.from(state);
  }
}

