/*
 * Minimal emulation of the CPython exception + traceback surface that this
 * program can actually reach.
 *
 * The reference build is a PyInstaller bundle, so frozen library frames print
 * their `File "...", line N, in name` header with no source line underneath
 * (the .py sources are not shipped), while frames from the frozen entry script
 * do show source and, on 3.11+, an anchor caret line.
 */

/** A frame as it appears in a printed traceback, innermost last. */
export function frame(file, line, name, source = null, caret = null) {
  return { file, line, name, source, caret };
}

/** Stand-in for Python's built-in ValueError. */
export class PyValueError extends Error {
  /**
   * @param {string} message  text after "ValueError: "
   * @param {object[]} libFrames  frames raised inside the library, outermost first
   */
  constructor(message, libFrames = []) {
    super(message);
    this.name = 'ValueError';
    this.libFrames = libFrames;
  }
}

