/*
 * Python `bytes` semantics: str.encode() and the exact repr() spelling that
 * `print(b'...')` produces.
 */

const BACKSLASH = 0x5c;
const TAB = 0x09;
const NEWLINE = 0x0a;
const CARRIAGE_RETURN = 0x0d;
const SINGLE_QUOTE = 0x27;
const DOUBLE_QUOTE = 0x22;

/** Equivalent of Python's `str.encode()` (UTF-8 by default). */
export function encodeUtf8(text) {
  return Uint8Array.from(Buffer.from(text, 'utf8'));
}

/**
 * Reproduce CPython's `repr(bytes)`.
 *
 * Quote selection matches CPython: single quotes normally, switching to double
 * quotes only when the data contains a `'` but no `"` -- so a payload holding
 * both quote characters stays single-quoted with `\'` escaped.
 *
 * Only backslash, tab, newline, carriage return and the active delimiter get
 * symbolic escapes; every other byte outside printable ASCII (0x20..0x7e) is
 * written as lowercase `\xNN`.
 */
export function reprBytes(bytes) {
  const data = Uint8Array.from(bytes);
  let hasSingle = false;
  let hasDouble = false;
  for (const byte of data) {
    if (byte === SINGLE_QUOTE) hasSingle = true;
    else if (byte === DOUBLE_QUOTE) hasDouble = true;
  }

  const quote = hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
  const quoteChar = String.fromCharCode(quote);

  let out = `b${quoteChar}`;
  for (const byte of data) {
    if (byte === BACKSLASH) out += '\\\\';
    else if (byte === TAB) out += '\\t';
    else if (byte === NEWLINE) out += '\\n';
    else if (byte === CARRIAGE_RETURN) out += '\\r';
    else if (byte === quote) out += `\\${quoteChar}`;
    else if (byte >= 0x20 && byte < 0x7f) out += String.fromCharCode(byte);
    else out += `\\x${byte.toString(16).padStart(2, '0')}`;
  }

  return out + quoteChar;
}

