/*
 * A small stand-in for the slice of `argparse.ArgumentParser` this program
 * uses: two required long options taking one value each, plus the automatic
 * -h/--help action.
 *
 * Reproduced behaviours that matter for output alignment:
 *   - `--opt value` and `--opt=value` are both accepted
 *   - long options may be abbreviated to any unambiguous prefix (allow_abbrev)
 *   - repeating an option keeps the last value
 *   - `--help` prints to stdout and exits 0
 *   - every parse error prints the usage line + `prog: error: ...` to stderr
 *     and exits 2
 *   - missing required options are listed in the order they were added
 *   - unknown tokens are collected and reported together, after the
 *     required-argument check
 */

const HELP_INDENT = '  ';
const MAX_HELP_POSITION = 24;

/** Does this token look like an option rather than a value? */
function looksLikeOption(token) {
  return token.length > 1 && token.startsWith('-');
}

export class ArgumentParser {
  constructor({ prog, stdout, stderr, exit } = {}) {
    this.prog = prog;
    this.stdout = stdout ?? ((text) => process.stdout.write(text));
    this.stderr = stderr ?? ((text) => process.stderr.write(text));
    this.exit = exit ?? ((code) => process.exit(code));

    this.actions = [
      {
        optionStrings: ['-h', '--help'],
        dest: 'help',
        isHelp: true,
        required: false,
        help: 'show this help message and exit',
      },
    ];
  }

  /**
   * Register a long option that consumes exactly one value.
   * `dest` is derived from the option string the way argparse derives it.
   */
  addArgument(optionString, { required = false, help = null } = {}) {
    const dest = optionString.replace(/^--/, '').replace(/-/g, '_');
    this.actions.push({
      optionStrings: [optionString],
      dest,
      metavar: dest.toUpperCase(),
      isHelp: false,
      required,
      help,
    });
    return this;
  }

  /** `-h, --help` / `--key KEY` -- how an action is spelled in help output. */
  formatInvocation(action) {
    if (action.isHelp) return action.optionStrings.join(', ');
    return `${action.optionStrings[0]} ${action.metavar}`;
  }

  formatUsage() {
    const parts = this.actions.map((action) =>
      action.isHelp ? '[-h]' : this.formatInvocation(action),
    );
    return `usage: ${this.prog} ${parts.join(' ')}\n`;
  }

  formatHelp() {
    // argparse aligns help text at min(longest invocation + indent + 2, 24).
    const widest = Math.max(
      ...this.actions.map((a) => this.formatInvocation(a).length + HELP_INDENT.length),
    );
    const helpPosition = Math.min(widest + 2, MAX_HELP_POSITION);

    const lines = [this.formatUsage().trimEnd(), '', 'options:'];
    for (const action of this.actions) {
      const invocation = HELP_INDENT + this.formatInvocation(action);
      if (action.help === null) {
        lines.push(invocation);
      } else {
        lines.push(invocation.padEnd(helpPosition) + action.help);
      }
    }
    return `${lines.join('\n')}\n`;
  }

  printHelpAndExit() {
    this.stdout(this.formatHelp());
    return this.exit(0);
  }

  /** Print usage + error to stderr and exit 2, exactly like argparse. */
  error(message) {
    this.stderr(this.formatUsage());
    this.stderr(`${this.prog}: error: ${message}\n`);
    return this.exit(2);
  }

  /**
   * Resolve an option token to a registered action.
   * Returns null when nothing matches (the token is then "unrecognized").
   */
  resolveOption(name) {
    const exact = this.actions.find((action) => action.optionStrings.includes(name));
    if (exact) return exact;

    // Abbreviations apply to long options only.
    if (!name.startsWith('--')) return null;
    const matches = [];
    for (const action of this.actions) {
      for (const optionString of action.optionStrings) {
        if (optionString.startsWith('--') && optionString.startsWith(name)) {
          matches.push({ action, optionString });
        }
      }
    }
    if (matches.length === 1) return matches[0].action;
    if (matches.length > 1) {
      const candidates = matches.map((m) => m.optionString).join(', ');
      this.error(`ambiguous option: ${name} could match ${candidates}`);
      return null;
    }
    return null;
  }

  parseArgs(argv) {
    const values = {};
    const extras = [];
    let index = 0;
    let onlyPositionalsRemain = false;

    while (index < argv.length) {
      const token = argv[index];

      if (onlyPositionalsRemain || !looksLikeOption(token)) {
        extras.push(token);
        index += 1;
        continue;
      }

      if (token === '--') {
        onlyPositionalsRemain = true;
        index += 1;
        continue;
      }

      const equalsAt = token.indexOf('=');
      const name = equalsAt === -1 ? token : token.slice(0, equalsAt);
      const inlineValue = equalsAt === -1 ? null : token.slice(equalsAt + 1);

      const action = this.resolveOption(name);
      if (!action) {
        extras.push(token);
        index += 1;
        continue;
      }

      if (action.isHelp) {
        return this.printHelpAndExit();
      }

      if (inlineValue !== null) {
        values[action.dest] = inlineValue;
        index += 1;
        continue;
      }

      const next = argv[index + 1];
      if (next === undefined || looksLikeOption(next)) {
        return this.error(`argument ${action.optionStrings[0]}: expected one argument`);
      }
      values[action.dest] = next;
      index += 2;
    }

    // Required options are reported together, in registration order.
    const missing = this.actions
      .filter((action) => action.required && values[action.dest] === undefined)
      .map((action) => action.optionStrings[0]);
    if (missing.length > 0) {
      return this.error(`the following arguments are required: ${missing.join(', ')}`);
    }

    if (extras.length > 0) {
      return this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

