/*
 * pyaes block-cipher modes of operation.
 *
 * Only ECB is needed here. Like pyaes, this mode is strictly single-block: it
 * applies no padding and rejects anything that is not exactly 16 bytes, so the
 * caller sees the same ValueError the Python version raises.
 */

import { AES, BLOCK_SIZE, isValidKeySize } from './aes.mjs';
import { PyValueError, frame } from '../python/errors.mjs';

/*
 * Traceback frames as the frozen reference build prints them. Source lines are
 * absent because PyInstaller does not ship the library's .py files.
 */
const KEY_SIZE_FRAMES = [
  frame('pyaes/aes.py', 304, '__init__'),
  frame('pyaes/aes.py', 134, '__init__'),
];
const ENCRYPT_FRAMES = [frame('pyaes/aes.py', 342, 'encrypt')];
const DECRYPT_FRAMES = [frame('pyaes/aes.py', 347, 'decrypt')];

export class AESModeOfOperationECB {
  static name = 'Electronic Codebook (ECB)';

  constructor(key) {
    if (!isValidKeySize(key.length)) {
      throw new PyValueError('Invalid key size', KEY_SIZE_FRAMES);
    }
    this._aes = new AES(key);
  }

  encrypt(plaintext) {
    if (plaintext.length !== BLOCK_SIZE) {
      throw new PyValueError('plaintext block must be 16 bytes', ENCRYPT_FRAMES);
    }
    return Uint8Array.from(this._aes.encryptBlock(plaintext));
  }

  decrypt(ciphertext) {
    if (ciphertext.length !== BLOCK_SIZE) {
      throw new PyValueError('ciphertext block must be 16 bytes', DECRYPT_FRAMES);
    }
    return Uint8Array.from(this._aes.decryptBlock(ciphertext));
  }
}

