/*
 * Port of /workspace/dataset/test13.py
 *
 * Round-trips one 16-byte block through AES-ECB and prints the ciphertext and
 * the recovered plaintext using Python's bytes repr.
 */

import * as pyaes from './lib/pyaes/index.mjs';
import { ArgumentParser } from './lib/python/argparse.mjs';
import { encodeUtf8, reprBytes } from './lib/python/bytes.mjs';
import { PyValueError, formatTraceback, frame } from './lib/python/errors.mjs';

// argparse takes prog from argv[0]; the reference build reports its own name.
const PROG = 'test13_executable';
const SCRIPT = 'test13.py';

/** print() -- str + '\n' to stdout. */
function print(text) {
  process.stdout.write(`${text}\n`);
}

/*
 * Traceback frames for the two reachable ValueErrors, matching the line
 * numbers, source text and 3.11 anchor carets of the original script.
 */
const CONSTRUCT_FRAMES = [
  frame(SCRIPT, 18, '<module>', 'main()'),
  frame(
    SCRIPT,
    11,
    'main',
    'aes = pyaes.AESModeOfOperationECB(args.key.encode())  # Initialize AES ECB cipher',
    '      ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^',
  ),
];
const ENCRYPT_FRAMES = [
  frame(SCRIPT, 18, '<module>', 'main()'),
  frame(
    SCRIPT,
    12,
    'main',
    'ciphertext = aes.encrypt(args.data.encode())  # Encrypt plaintext',
    '             ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^',
  ),
];

function main() {
  const parser = new ArgumentParser({ prog: PROG });
  parser.addArgument('--key', { required: true }); // 16 bytes key
  parser.addArgument('--data', { required: true }); // 16 bytes data
  const args = parser.parseArgs(process.argv.slice(2));

  // Test round-trip encryption/decryption with ECB
  let aes;
  try {
    aes = new pyaes.AESModeOfOperationECB(encodeUtf8(args.key)); // Initialize AES ECB cipher
  } catch (error) {
    throw attachFrames(error, CONSTRUCT_FRAMES);
  }

  let ciphertext;
  try {
    ciphertext = aes.encrypt(encodeUtf8(args.data)); // Encrypt plaintext
  } catch (error) {
    throw attachFrames(error, ENCRYPT_FRAMES);
  }

  const plaintext = aes.decrypt(ciphertext); // Decrypt ciphertext back
  print(reprBytes(ciphertext));
  print(reprBytes(plaintext));
}

/** Tag a PyValueError with the script-level frames of its raise site. */
function attachFrames(error, frames) {
  if (error instanceof PyValueError) error.scriptFrames = frames;
  return error;
}

try {
  main();
} catch (error) {
  if (!(error instanceof PyValueError)) throw error;
  process.stderr.write(`${formatTraceback(error, error.scriptFrames ?? [])}\n`);
