/*
 * Emulation of Python's `linecache` module.
 *
 * This matters for output fidelity: the reference build is frozen, so its
 * traceback frames name bare relative paths like "test13.py" and "pyaes/aes.py".
 * CPython resolves those through linecache, which searches the *current working
 * directory* -- so whether a traceback shows source lines depends entirely on
 * whether a matching file happens to sit next to where the program was run.
 *
 * Run from the directory holding test13.py, tracebacks include source and caret
 * lines; run from anywhere else, they show only the `File "...", line N` header.
 */

import { readFileSync } from 'node:fs';

const cache = new Map();

/** Split a file into lines, keeping the trailing newline on each (as Python does). */
function readLines(filename) {
  if (cache.has(filename)) return cache.get(filename);

  let lines;
  try {
    lines = readFileSync(filename, 'utf8').match(/[^\n]*\n|[^\n]+/g) ?? [];
  } catch {
    lines = null; // missing or unreadable -- linecache yields '' for every line
  }
  cache.set(filename, lines);
  return lines;
}

/**
 * Return line `lineno` (1-based) of `filename`, including its trailing newline,
 * or '' when the file or line does not exist.
 */
export function getline(filename, lineno) {
  const lines = readLines(filename);
  if (lines === null || lineno < 1 || lineno > lines.length) return '';
  return lines[lineno - 1];
}

/**
 * Port of CPython's `traceback._byte_offset_to_character_offset`.
 *
 * Anchor columns recorded in a code object are UTF-8 *byte* offsets, but the
 * caret line is laid out in characters. Truncating mid-sequence decodes with
 * replacement, exactly like Python's errors="replace".
 */
export function byteOffsetToCharacterOffset(text, offset) {
  const encoded = Buffer.from(text, 'utf8');
  return encoded.subarray(0, offset).toString('utf8').length;
}

