/*
 * Minimal emulation of the CPython exception + traceback surface that this
 * program can reach.
 *
 * Frames carry the anchor columns baked into the original code objects rather
 * than pre-rendered text, because the source and caret lines are reconstructed
 * at print time from whatever `linecache` can find on disk -- see linecache.mjs
 * for why that lookup is working-directory dependent.
 */

import { getline, byteOffsetToCharacterOffset } from './linecache.mjs';

/**
 * Describe one traceback frame.
 *
 * @param {string} file    path as recorded in the code object
 * @param {number} line    1-based line number
 * @param {string} name    enclosing function name, or '<module>'
 * @param {number|null} colno     UTF-8 byte offset where the anchor starts
 * @param {number|null} endColno  UTF-8 byte offset just past the anchor
 */
export function frame(file, line, name, colno = null, endColno = null) {
  return { file, line, name, colno, endColno };
}

/** Stand-in for Python's built-in ValueError. */
export class PyValueError extends Error {
  /**
   * @param {string} message  text after "ValueError: "
   * @param {object[]} libFrames  frames raised inside the library, outermost first
   */
  constructor(message, libFrames = []) {
    super(message);
    this.name = 'ValueError';
    this.libFrames = libFrames;
  }
}

/**
 * Render one frame, following CPython 3.11's `StackSummary.format_frame_summary`.
 *
 * The source line is printed stripped and re-indented by four spaces. The caret
 * line is then positioned by translating the anchor's byte offsets into
 * character offsets and subtracting the whitespace that the strip removed --
 * which is why an anchor can end up clipped when the file on disk no longer
 * matches the code object it was compiled from.
 */
function formatFrame({ file, line, name, colno, endColno }) {
  const rendered = [`  File "${file}", line ${line}, in ${name}`];

  const rawLine = getline(file, line);
  const strippedLine = rawLine.trim();
  if (!strippedLine) return rendered; // no source available: header only
  rendered.push(`    ${strippedLine}`);

  if (colno === null || endColno === null) return rendered;

  const strippedCharacters = rawLine.length - strippedLine.length;
  const startOffset = byteOffsetToCharacterOffset(rawLine, colno) + 1;
  const endOffset = byteOffsetToCharacterOffset(rawLine, endColno) + 1;

  // Carets are suppressed when the anchor already spans the whole statement.
  if (endOffset - startOffset < strippedLine.length) {
    const pad = ' '.repeat(Math.max(0, startOffset - strippedCharacters));
    const carets = '^'.repeat(Math.max(0, endOffset - startOffset));
    rendered.push(`    ${pad}${carets}`);
  }

  return rendered;
}

/**
 * Build the full `Traceback (most recent call last):` block for an exception.
 *
 * @param {PyValueError} error
 * @param {object[]} scriptFrames  entry-script frames, outermost first
 */
export function formatTraceback(error, scriptFrames = []) {
  const frames = [...scriptFrames, ...(error.libFrames || [])];
  const lines = ['Traceback (most recent call last):'];
  for (const item of frames) lines.push(...formatFrame(item));
  lines.push(`${error.name}: ${error.message}`);
  return lines.join('\n');
}

